using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;using EchoSphere.Core;using EchoSphere.Presentation;
public static class UiPolishLayout {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 sealed class NoBackdrops:INativeUiBackdrops {sealed class Lease:IDisposable{public void Dispose(){}}public IDisposable RegisterNativeBackdrop(VisualElement e,float sigma)=>new Lease();}
 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");var asm=typeof(NativeUpgradeView).Assembly;var iconType=asm.GetType("EchoSphere.Presentation.NativeContentIcon");var merchantType=asm.GetType("EchoSphere.Presentation.NativeMerchantView");var catalog=Resources.Load<NativeArchiveCatalog>("EchoSphere/NativeArchiveCatalog");
 object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,F).Invoke(o,a);
 var host=new GameObject("Owned UI layout acceptance");var panel=ScriptableObject.CreateInstance<PanelSettings>();panel.themeStyleSheet=Resources.Load<ThemeStyleSheet>("EchoSphere/SourceUiTheme");panel.scale=1;panel.sortingOrder=200000;var target=new RenderTexture(720,900,0,RenderTextureFormat.ARGB32);target.Create();panel.targetTexture=target;var doc=host.AddComponent<UIDocument>();doc.panelSettings=panel;var root=doc.rootVisualElement;root.style.position=Position.Absolute;root.style.left=root.style.top=0;root.style.width=720;root.style.height=900;root.style.backgroundColor=new Color(.015f,.025f,.045f);var boundsStyle=Resources.Load<StyleSheet>("EchoSphere/NativeTextBounds");root.styleSheets.Add(boundsStyle);
 var cases=new List<(bool ru,float w,string branch)>();foreach(bool ru in new[]{true,false})foreach(float w in new[]{280f,360f,640f})foreach(SphereId sphere in Enum.GetValues(typeof(SphereId)))foreach(var branch in SphereEvolutionCatalog.GetBranches(sphere))cases.Add((ru,w,branch.Id));
 Application.runInBackground=true;EditorApplication.isPaused=false;int index=-1,frame=0,last=-1,checks=0,layouts=0;double deadline=EditorApplication.timeSinceStartup+240;NativeUpgradeView upgrade=null;object merchant=null;string phase="icons";var log=new List<string>();Directory.CreateDirectory("Library/ui-polish");void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
 void Capture(string name){var old=RenderTexture.active;var image=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);try{RenderTexture.active=target;image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();File.WriteAllBytes("Library/ui-polish/"+name+".png",image.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(image);}}
 void Icons(){root.style.width=720;root.style.height=900;root.style.flexDirection=FlexDirection.Row;root.style.flexWrap=Wrap.Wrap;foreach(var item in ArtifactRewardRules.Catalog(true)){var tile=new VisualElement();tile.style.width=60;tile.style.height=72;tile.style.alignItems=Align.Center;tile.style.justifyContent=Justify.Center;root.Add(tile);var icon=(VisualElement)Activator.CreateInstance(iconType,F,null,new object[]{"artifact:"+item.Id,new Color(.5f,.85f,1),44f},null);tile.Add(icon);var label=new Label(item.Id.Replace("_"," "));label.style.fontSize=7;label.style.color=Color.gray;label.style.whiteSpace=WhiteSpace.Normal;label.style.unityTextAlign=TextAnchor.MiddleCenter;tile.Add(label);}}
 void Next(){upgrade?.Dispose();upgrade=null;root.Clear();root.style.flexDirection=FlexDirection.Column;root.style.flexWrap=Wrap.NoWrap;frame=0;index++;if(index<cases.Count){var c=cases[index];root.style.width=c.w;root.style.height=560;upgrade=new NativeUpgradeView(root,new NoBackdrops(),_=>{},_=>{},()=>{});var choices=new List<NativeUpgradeView.Choice>();int i=0;foreach(var final in SphereEvolutionCatalog.GetFinals(c.branch)){string id="sphere-final:"+c.branch.Substring(0,c.branch.IndexOf('_'))+":"+c.branch+":"+i;var e=catalog.Entries.FirstOrDefault(e=>e.id==id);choices.Add(new NativeUpgradeView.Choice{Index=i++,Key=final.Id,Name=e?.Name(c.ru)??final.Name,Description=e?.Description(c.ru)??final.Description,Level=c.ru?"УРОВЕНЬ VII":"LEVEL VII",Category=c.ru?"МУТАЦИЯ СФЕРЫ":"SPHERE MUTATION",CanLock=true,ElementCard=true,Element=c.ru?"РЕЗОНАНС":"RESONANCE",ElementColor="#8de5ff"});}upgrade.Bind(new NativeUpgradeView.State{Russian=c.ru,Title=c.ru?"Выберите мутацию":"Choose a mutation",Signature=index.ToString(),Choices=choices,ShowReroll=true,CanReroll=true,Reroll=c.ru?"Обновить выбор":"Refresh choices"});phase="upgrade";}else if(index<cases.Count+4){root.style.width=index%2==0?280:360;root.style.height=560;var state=RunEconomyRules.Create(111);RunEconomyRules.AdvanceMerchant(state,390);RunEconomyRules.Prepare(state,new List<string>());state.Open=true;state.Echo=9999;merchant=Activator.CreateInstance(merchantType,F,null,new object[]{root,(Action)(()=>{}),(Action)(()=>{}),(Action<int>)(_=>{})},null);Call(merchant,"Bind",state,new List<string>(),index%2==0,390d,true,true,false);phase="merchant";}else phase="done";}
 EditorApplication.CallbackFunction tick=null;void Finish(string status){EditorApplication.update-=tick;try{upgrade?.Dispose();doc.panelSettings=null;UnityEngine.Object.DestroyImmediate(host);UnityEngine.Object.DestroyImmediate(panel);target.Release();UnityEngine.Object.DestroyImmediate(target);}finally{File.WriteAllText("Library/ui-polish/layout.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status,checks,layouts,cases=cases.Count,log,scope="actual attached UI Toolkit layouts, RU/EN mutation finals, 280/360/640 logical widths, merchant selection grid, vector artifact sheet; not device"}));}}
 Icons();tick=()=>{try{EditorApplication.QueuePlayerLoopUpdate();if(!Application.isPlaying||EditorApplication.timeSinceStartup>deadline){Finish("FAIL deadline");return;}if(Time.frameCount==last)return;last=Time.frameCount;frame++;if(phase=="icons"){if(frame<8)return;Check(root.panel!=null,"icon panel attached");Capture("artifact-icons");Next();return;}if(phase=="done"){Finish("PASS");return;}if(upgrade!=null)upgrade.Prepare(1,root.resolvedStyle.width);if(frame<6)return;
  var content=phase=="upgrade"?root.Q<VisualElement>("upgrade-content"):root.Q<VisualElement>("merchant-panel");Check(content!=null&&content.worldBound.width>0,"laid out content");Check(content.worldBound.xMin>=root.worldBound.xMin-1&&content.worldBound.xMax<=root.worldBound.xMax+1,"horizontal content bounds "+index);
  foreach(var label in content.Query<Label>().ToList()){if(label.resolvedStyle.display==DisplayStyle.None||label.worldBound.width<=0)continue;Check(float.IsFinite(label.worldBound.xMax+label.worldBound.yMax),"finite text");if(label.name=="merchant-price")Check(label.MeasureTextSize(label.text,0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined).x<=label.contentRect.width+1,"complete merchant price "+label.text);Check(label.worldBound.xMin>=root.worldBound.xMin-1&&label.worldBound.xMax<=root.worldBound.xMax+1,"text outside horizontal viewport "+index+" "+label.name+" "+label.text);}
  var scroll=phase=="upgrade"?root.Q<ScrollView>("upgrade-scroll"):root.Q<ScrollView>("merchant-stock");Check(scroll.worldBound.yMin>=root.worldBound.yMin-1&&scroll.worldBound.yMax<=root.worldBound.yMax+1,"scroll viewport vertical bounds "+index);
  if(phase=="upgrade"){Check(upgrade.Ready,"native painted upgrade ready");var buttons=root.Query<Button>().ToList();Check(buttons.Count>=3,"all choices retained");if(index==0)Capture("mutation-ru-compact");if(index==90)Capture("mutation-en-compact");}else{Check(root.Q<Button>("merchant-buy")!=null&&root.Q<Button>("merchant-close")!=null,"merchant purchase and close");if(index==cases.Count)Capture("merchant-compact");}
  layouts++;Next();
 }catch(Exception ex){log.Add(ex.ToString());Finish("FAIL");}};EditorApplication.update+=tick;return new{status="queued",cases=cases.Count+4,artifactIcons=ArtifactRewardRules.Catalog(true).Count()};
 }
}
